  1→use bigdecimal::BigDecimal;
  2→use spectraplex_core::models::{EntryType, LedgerEntry, Transaction};
  3→use std::str::FromStr;
  4→use tracing::warn;
  5→
  6→use crate::deterministic_id;
  7→use crate::hyperliquid::{HlFill, HlFundingEntry, HlLedgerUpdate};
  8→
  9→pub fn parse_hyperliquid_transaction(tx: &Transaction) -> anyhow::Result<Vec<LedgerEntry>> {
 10→    let raw = &tx.raw_metadata;
 11→    let entry_type = raw["type"].as_str().unwrap_or("unknown");
 12→
 13→    match entry_type {
 14→        "fill" => parse_fill(tx, &raw["data"]),
 15→        "funding" => parse_funding(tx, &raw["data"]),
 16→        "ledger_update" => parse_ledger_update(tx, &raw["data"]),
 17→        other => {
 18→            warn!(tx_hash = %tx.tx_hash, r#type = %other, "Unknown Hyperliquid transaction type");
 19→            Ok(vec![])
 20→        }
 21→    }
 22→}
 23→
 24→fn parse_fill(tx: &Transaction, data: &serde_json::Value) -> anyhow::Result<Vec<LedgerEntry>> {
 25→    let fill: HlFill = serde_json::from_value(data.clone())?;
 26→    let mut entries = Vec::new();
 27→    let mut entry_index: u32 = 0;
 28→
 29→    let size = BigDecimal::from_str(&fill.sz).unwrap_or_default();
 30→    let price = BigDecimal::from_str(&fill.px).unwrap_or_default();
 31→
 32→    // The trade itself: amount is the size, fiat_value is size * price
 33→    let fiat_value = &size * &price;
 34→
 35→    // Determine sign based on side: B (buy) = positive, A/S (sell) = negative
 36→    let signed_size = if fill.side == "B" { size } else { -size };
 37→
 38→    entries.push(LedgerEntry {
 39→        id: deterministic_id(tx.id, entry_index),
 40→        transaction_id: tx.id,
 41→        user_id: tx.user_id,
 42→        wallet_address: tx.wallet_address.clone(),
 43→        asset_symbol: fill.coin.clone(),
 44→        amount: signed_size,
 45→        entry_type: EntryType::Trade,
 46→        fiat_value: Some(fiat_value),
 47→    });
 48→    entry_index += 1;
 49→
 50→    // Fee entry (if present)
 51→    if let Some(ref fee_str) = fill.fee {
 52→        let fee = BigDecimal::from_str(fee_str).unwrap_or_default();
 53→        if fee != BigDecimal::from(0) {
 54→            let fee_token = fill.fee_token.as_deref().unwrap_or("USDC");
 55→            entries.push(LedgerEntry {
 56→                id: deterministic_id(tx.id, entry_index),
 57→                transaction_id: tx.id,
 58→                user_id: tx.user_id,
 59→                wallet_address: tx.wallet_address.clone(),
 60→                asset_symbol: fee_token.to_string(),
 61→                amount: -fee.abs(), // Fees are always outgoing
 62→                entry_type: EntryType::Fee,
 63→                fiat_value: None,
 64→            });
 65→            entry_index += 1;
 66→        }
 67→    }
 68→
 69→    // Closed PnL as income (if nonzero)
 70→    if let Some(ref pnl_str) = fill.closed_pnl {
 71→        let pnl = BigDecimal::from_str(pnl_str).unwrap_or_default();
 72→        if pnl != BigDecimal::from(0) {
 73→            entries.push(LedgerEntry {
 74→                id: deterministic_id(tx.id, entry_index),
 75→                transaction_id: tx.id,
 76→                user_id: tx.user_id,
 77→                wallet_address: tx.wallet_address.clone(),
 78→                asset_symbol: "USDC".to_string(),
 79→                amount: pnl,
 80→                entry_type: EntryType::Income,
 81→                fiat_value: None,
 82→            });
 83→            entry_index += 1;
 84→        }
 85→    }
 86→
 87→    let _ = entry_index;
 88→    Ok(entries)
 89→}
 90→
 91→fn parse_funding(tx: &Transaction, data: &serde_json::Value) -> anyhow::Result<Vec<LedgerEntry>> {
 92→    let funding: HlFundingEntry = serde_json::from_value(data.clone())?;
 93→    let amount = BigDecimal::from_str(&funding.usdc).unwrap_or_default();
 94→
 95→    // Funding payments: positive = received, negative = paid
 96→    Ok(vec![LedgerEntry {
 97→        id: deterministic_id(tx.id, 0),
 98→        transaction_id: tx.id,
 99→        user_id: tx.user_id,
100→        wallet_address: tx.wallet_address.clone(),
101→        asset_symbol: "USDC".to_string(),
102→        amount,
103→        entry_type: EntryType::Fee,
104→        fiat_value: None,
105→    }])
106→}
107→
108→fn parse_ledger_update(
109→    tx: &Transaction,
110→    data: &serde_json::Value,
111→) -> anyhow::Result<Vec<LedgerEntry>> {
112→    let update: HlLedgerUpdate = serde_json::from_value(data.clone())?;
113→    let delta = &update.delta;
114→
115→    let delta_type = delta["type"].as_str().unwrap_or("unknown");
116→
117→    match delta_type {
118→        "deposit" => {
119→            let usdc = delta["usdc"].as_str().unwrap_or("0");
120→            let amount = BigDecimal::from_str(usdc).unwrap_or_default();
121→            Ok(vec![LedgerEntry {
122→                id: deterministic_id(tx.id, 0),
123→                transaction_id: tx.id,
124→                user_id: tx.user_id,
125→                wallet_address: tx.wallet_address.clone(),
126→                asset_symbol: "USDC".to_string(),
127→                amount,
128→                entry_type: EntryType::Transfer,
129→                fiat_value: None,
130→            }])
131→        }
132→        "withdraw" => {
133→            let usdc = delta["usdc"].as_str().unwrap_or("0");
134→            let amount = BigDecimal::from_str(usdc).unwrap_or_default();
135→            Ok(vec![LedgerEntry {
136→                id: deterministic_id(tx.id, 0),
137→                transaction_id: tx.id,
138→                user_id: tx.user_id,
139→                wallet_address: tx.wallet_address.clone(),
140→                asset_symbol: "USDC".to_string(),
141→                amount: -amount.abs(),
142→                entry_type: EntryType::Transfer,
143→                fiat_value: None,
144→            }])
145→        }
146→        "liquidation" => {
147→            // Liquidation can have complex delta structures; store a generic entry
148→            let usdc = delta["usdc"]
149→                .as_str()
150→                .or_else(|| delta["accountValue"].as_str())
151→                .unwrap_or("0");
152→            let amount = BigDecimal::from_str(usdc).unwrap_or_default();
153→            Ok(vec![LedgerEntry {
154→                id: deterministic_id(tx.id, 0),
155→                transaction_id: tx.id,
156→                user_id: tx.user_id,
157→                wallet_address: tx.wallet_address.clone(),
158→                asset_symbol: "USDC".to_string(),
159→                amount,
160→                entry_type: EntryType::Trade,
161→                fiat_value: None,
162→            }])
163→        }
164→        _ => {
165→            warn!(tx_hash = %tx.tx_hash, delta_type = %delta_type, "Unknown ledger update type");
166→            Ok(vec![])
167→        }
168→    }
169→}
