182→/// Extract Hyperliquid token transfers from a raw transaction.
183→///
184→/// Deposits and withdrawals are modeled as USDC transfers between an external
185→/// source/destination and the user's Hyperliquid account.
186→pub fn extract_hyperliquid_token_transfers(
187→    raw_tx_id: Option<Uuid>,
188→    network: &str,
189→    wallet_address: &str,
190→    raw_metadata: &serde_json::Value,
191→) -> Vec<TokenTransfer> {
192→    let entry_type = raw_metadata["type"].as_str().unwrap_or("unknown");
193→
194→    match entry_type {
195→        "ledger_update" => {
196→            let data = &raw_metadata["data"];
197→            let delta = &data["delta"];
198→            let delta_type = delta["type"].as_str().unwrap_or("unknown");
199→
200→            match delta_type {
201→                "deposit" => {
202→                    let usdc = delta["usdc"].as_str().unwrap_or("0");
203→                    let amount = BigDecimal::from_str(usdc).unwrap_or_default();
204→                    if amount == BigDecimal::from(0) {
205→                        return vec![];
206→                    }
207→                    vec![TokenTransfer {
208→                        id: Uuid::new_v4(),
209→                        raw_transaction_id: raw_tx_id,
210→                        network: network.to_string(),
211→                        token_address: "USDC".to_string(),
212→                        token_symbol: Some("USDC".to_string()),
213→                        from_address: "external".to_string(),
214→                        to_address: wallet_address.to_string(),
215→                        amount,
216→                        decimals: 6,
217→                        dataset_version_id: None,
218→                        created_at: Utc::now(),
219→                    }]
220→                }
221→                "withdraw" => {
222→                    let usdc = delta["usdc"].as_str().unwrap_or("0");
223→                    let amount = BigDecimal::from_str(usdc).unwrap_or_default().abs();
224→                    if amount == BigDecimal::from(0) {
225→                        return vec![];
226→                    }
227→                    vec![TokenTransfer {
228→                        id: Uuid::new_v4(),
229→                        raw_transaction_id: raw_tx_id,
230→                        network: network.to_string(),
231→                        token_address: "USDC".to_string(),
232→                        token_symbol: Some("USDC".to_string()),
233→                        from_address: wallet_address.to_string(),
234→                        to_address: "external".to_string(),
235→                        amount,
236→                        decimals: 6,
237→                        dataset_version_id: None,
238→                        created_at: Utc::now(),
239→                    }]
240→                }
241→                _ => vec![],
242→            }
243→        }
244→        _ => vec![],
245→    }
246→}
