248→// ---------------------------------------------------------------------------
249→// Native Balance Delta extraction (P3-W2)
250→// ---------------------------------------------------------------------------
251→
252→/// Extract Hyperliquid native balance deltas from a raw transaction.
253→///
254→/// On Hyperliquid, the "native" token is USDC (the settlement currency).
255→/// Balance deltas are extracted from fill and funding events as changes to the
256→/// account's USDC balance.
257→pub fn extract_hyperliquid_native_balance_deltas(
258→    raw_tx_id: Option<Uuid>,
259→    network: &str,
260→    wallet_address: &str,
261→    raw_metadata: &serde_json::Value,
262→) -> Vec<NativeBalanceDelta> {
263→    let entry_type = raw_metadata["type"].as_str().unwrap_or("unknown");
264→
265→    match entry_type {
266→        "fill" => {
267→            let data = &raw_metadata["data"];
268→            let fill: HlFill = match serde_json::from_value(data.clone()) {
269→                Ok(f) => f,
270→                Err(_) => return vec![],
271→            };
272→
273→            // Fee and closed PnL represent USDC balance changes
274→            let fee = fill
275→                .fee
276→                .as_deref()
277→                .and_then(|f| BigDecimal::from_str(f).ok())
278→                .unwrap_or_default();
279→            let pnl = fill
280→                .closed_pnl
281→                .as_deref()
282→                .and_then(|p| BigDecimal::from_str(p).ok())
283→                .unwrap_or_default();
284→
285→            // Total USDC delta from this fill = -fee + closed_pnl
286→            let delta = &pnl - &fee.abs();
287→
288→            if delta == BigDecimal::from(0) {
289→                return vec![];
290→            }
291→
292→            vec![NativeBalanceDelta {
293→                id: Uuid::new_v4(),
294→                raw_transaction_id: raw_tx_id,
295→                network: network.to_string(),
296→                account_address: wallet_address.to_string(),
297→                native_token: "USDC".to_string(),
298→                pre_balance: BigDecimal::from(0), // Not available from fill data
299→                post_balance: BigDecimal::from(0), // Not available from fill data
300→                delta,
301→                is_fee_payer: true, // The user always pays fees on HL
302→                dataset_version_id: None,
303→                created_at: Utc::now(),
304→            }]
305→        }
306→        "funding" => {
307→            let data = &raw_metadata["data"];
308→            let funding: HlFundingEntry = match serde_json::from_value(data.clone()) {
309→                Ok(f) => f,
310→                Err(_) => return vec![],
311→            };
312→
313→            let delta = BigDecimal::from_str(&funding.usdc).unwrap_or_default();
314→            if delta == BigDecimal::from(0) {
315→                return vec![];
316→            }
317→
318→            vec![NativeBalanceDelta {
319→                id: Uuid::new_v4(),
320→                raw_transaction_id: raw_tx_id,
321→                network: network.to_string(),
322→                account_address: wallet_address.to_string(),
323→                native_token: "USDC".to_string(),
324→                pre_balance: BigDecimal::from(0),
325→                post_balance: BigDecimal::from(0),
326→                delta,
327→                is_fee_payer: false,
328→                dataset_version_id: None,
329→                created_at: Utc::now(),
330→            }]
331→        }
332→        _ => vec![],
333→    }
334→}
