  1→//! V2 repository methods for canonical bronze data and control-plane tables.
  2→//!
  3→//! All methods are added as `impl Repository` so callers use the same
  4→//! `Repository` value they already hold for V1 wallet-scoped queries.
  5→
  6→use chrono::{DateTime, Utc};
  7→use spectraplex_core::materializer::{DecodedEvent, NativeBalanceDelta, TokenTransfer};
  8→use spectraplex_core::v2::{
  9→    ChainFamily, Checkpoint, DatasetVersion, DatasetVersionStatus, IndexTarget, IngestionRun,
 10→    Network, RawTransaction, TargetKind, TargetMatch, TargetMode,
 11→};
 12→use sqlx::Row;
 13→use uuid::Uuid;
 14→
 15→use crate::repo::Repository;
 16→
 17→// ---------------------------------------------------------------------------
 18→// Enum ↔ SQL string helpers
 19→// ---------------------------------------------------------------------------
 20→
 21→/// Convert a `ChainFamily` to the string used by `chain_family_enum` in SQL.
 22→pub fn chain_family_to_sql(cf: &ChainFamily) -> &'static str {
 23→    match cf {
 24→        ChainFamily::Solana => "solana",
 25→        ChainFamily::Evm => "evm",
 26→        ChainFamily::Hyperliquid => "hyperliquid",
 27→    }
 28→}
 29→
 30→/// Parse a SQL `chain_family_enum` string back to `ChainFamily`.
 31→pub fn sql_to_chain_family(s: &str) -> anyhow::Result<ChainFamily> {
 32→    match s {
 33→        "solana" => Ok(ChainFamily::Solana),
 34→        "evm" => Ok(ChainFamily::Evm),
 35→        "hyperliquid" => Ok(ChainFamily::Hyperliquid),
 36→        _ => Err(anyhow::anyhow!("Unknown chain_family: {s}")),
 37→    }
 38→}
 39→
 40→/// Convert a `TargetKind` to the string used by `target_kind_enum` in SQL.
 41→pub fn target_kind_to_sql(tk: &TargetKind) -> &'static str {
 42→    match tk {
 43→        TargetKind::Wallet => "wallet",
 44→        TargetKind::Contract => "contract",
 45→        TargetKind::Program => "program",
 46→        TargetKind::Account => "account",
 47→        TargetKind::TopicFilter => "topic_filter",
 48→        TargetKind::Market => "market",
 49→        TargetKind::Pool => "pool",
 50→        TargetKind::Protocol => "protocol",
 51→    }
 52→}
 53→
 54→/// Parse a SQL `target_kind_enum` string back to `TargetKind`.
 55→pub fn sql_to_target_kind(s: &str) -> anyhow::Result<TargetKind> {
 56→    match s {
 57→        "wallet" => Ok(TargetKind::Wallet),
 58→        "contract" => Ok(TargetKind::Contract),
 59→        "program" => Ok(TargetKind::Program),
 60→        "account" => Ok(TargetKind::Account),
 61→        "topic_filter" => Ok(TargetKind::TopicFilter),
 62→        "market" => Ok(TargetKind::Market),
 63→        "pool" => Ok(TargetKind::Pool),
 64→        "protocol" => Ok(TargetKind::Protocol),
 65→        _ => Err(anyhow::anyhow!("Unknown target_kind: {s}")),
 66→    }
 67→}
 68→
 69→/// Convert a `TargetMode` to the string used by `target_mode_enum` in SQL.
 70→pub fn target_mode_to_sql(tm: &TargetMode) -> &'static str {
 71→    match tm {
 72→        TargetMode::Backfill => "backfill",
 73→        TargetMode::Stream => "stream",
 74→        TargetMode::Both => "both",
 75→    }
 76→}
 77→
 78→/// Parse a SQL `target_mode_enum` string back to `TargetMode`.
 79→pub fn sql_to_target_mode(s: &str) -> anyhow::Result<TargetMode> {
 80→    match s {
 81→        "backfill" => Ok(TargetMode::Backfill),
 82→        "stream" => Ok(TargetMode::Stream),
 83→        "both" => Ok(TargetMode::Both),
 84→        _ => Err(anyhow::anyhow!("Unknown target_mode: {s}")),
 85→    }
 86→}
 87→
 88→/// Convert a `DatasetVersionStatus` to the string used in SQL.
 89→pub fn dataset_version_status_to_sql(s: &DatasetVersionStatus) -> &'static str {
 90→    match s {
 91→        DatasetVersionStatus::Active => "active",
 92→        DatasetVersionStatus::Superseded => "superseded",
 93→        DatasetVersionStatus::Failed => "failed",
 94→    }
 95→}
 96→
 97→/// Parse a SQL status string back to `DatasetVersionStatus`.
 98→pub fn sql_to_dataset_version_status(s: &str) -> anyhow::Result<DatasetVersionStatus> {
 99→    match s {
