//! V2 repository methods for canonical bronze data and control-plane tables.
//!
//! All methods are added as `impl Repository` so callers use the same
//! `Repository` value they already hold for V1 wallet-scoped queries.

use chrono::{DateTime, Utc};
use spectraplex_core::materializer::{DecodedEvent, NativeBalanceDelta, TokenTransfer};
use spectraplex_core::v2::{
    ChainFamily, Checkpoint, DatasetVersion, DatasetVersionStatus, IndexTarget, IngestionRun,
    Network, RawTransaction, TargetKind, TargetMatch, TargetMode,
};
use sqlx::Row;
use uuid::Uuid;

use crate::repo::Repository;

// ---------------------------------------------------------------------------
// Enum ↔ SQL string helpers
// ---------------------------------------------------------------------------

/// Convert a `ChainFamily` to the string used by `chain_family_enum` in SQL.
pub fn chain_family_to_sql(cf: &ChainFamily) -> &'static str {
    match cf {
        ChainFamily::Solana => "solana",
        ChainFamily::Evm => "evm",
        ChainFamily::Hyperliquid => "hyperliquid",
    }
}

/// Parse a SQL `chain_family_enum` string back to `ChainFamily`.
pub fn sql_to_chain_family(s: &str) -> anyhow::Result<ChainFamily> {
    match s {
        "solana" => Ok(ChainFamily::Solana),
        "evm" => Ok(ChainFamily::Evm),
        "hyperliquid" => Ok(ChainFamily::Hyperliquid),
        _ => Err(anyhow::anyhow!("Unknown chain_family: {s}")),
    }
}

/// Convert a `TargetKind` to the string used by `target_kind_enum` in SQL.
pub fn target_kind_to_sql(tk: &TargetKind) -> &'static str {
    match tk {
        TargetKind::Wallet => "wallet",
        TargetKind::Contract => "contract",
        TargetKind::Program => "program",
        TargetKind::Account => "account",
        TargetKind::TopicFilter => "topic_filter",
        TargetKind::Market => "market",
        TargetKind::Pool => "pool",
        TargetKind::Protocol => "protocol",
    }
}

/// Parse a SQL `target_kind_enum` string back to `TargetKind`.
pub fn sql_to_target_kind(s: &str) -> anyhow::Result<TargetKind> {
    match s {
        "wallet" => Ok(TargetKind::Wallet),
        "contract" => Ok(TargetKind::Contract),
        "program" => Ok(TargetKind::Program),
        "account" => Ok(TargetKind::Account),
        "topic_filter" => Ok(TargetKind::TopicFilter),
        "market" => Ok(TargetKind::Market),
        "pool" => Ok(TargetKind::Pool),
        "protocol" => Ok(TargetKind::Protocol),
        _ => Err(anyhow::anyhow!("Unknown target_kind: {s}")),
    }
}

/// Convert a `TargetMode` to the string used by `target_mode_enum` in SQL.
pub fn target_mode_to_sql(tm: &TargetMode) -> &'static str {
    match tm {
        TargetMode::Backfill => "backfill",
        TargetMode::Stream => "stream",
        TargetMode::Both => "both",
    }
}

/// Parse a SQL `target_mode_enum` string back to `TargetMode`.
pub fn sql_to_target_mode(s: &str) -> anyhow::Result<TargetMode> {
    match s {
        "backfill" => Ok(TargetMode::Backfill),
        "stream" => Ok(TargetMode::Stream),
        "both" => Ok(TargetMode::Both),
        _ => Err(anyhow::anyhow!("Unknown target_mode: {s}")),
    }
}

/// Convert a `DatasetVersionStatus` to the string used in SQL.
pub fn dataset_version_status_to_sql(s: &DatasetVersionStatus) -> &'static str {
    match s {
        DatasetVersionStatus::Active => "active",
        DatasetVersionStatus::Superseded => "superseded",
        DatasetVersionStatus::Failed => "failed",
    }
}

/// Parse a SQL status string back to `DatasetVersionStatus`.
pub fn sql_to_dataset_version_status(s: &str) -> anyhow::Result<DatasetVersionStatus> {
    match s {
        "active" => Ok(DatasetVersionStatus::Active),
        "superseded" => Ok(DatasetVersionStatus::Superseded),
        "failed" => Ok(DatasetVersionStatus::Failed),
        _ => Err(anyhow::anyhow!("Unknown dataset_version_status: {s}")),
    }
}

// ---------------------------------------------------------------------------
// Row-mapping helpers
// ---------------------------------------------------------------------------

fn row_to_network(row: &sqlx::postgres::PgRow) -> anyhow::Result<Network> {
    let family_str: String = row.try_get("chain_family")?;
    Ok(Network {
        id: row.try_get("id")?,
        chain_family: sql_to_chain_family(&family_str)?,
        display_name: row.try_get("display_name")?,
        is_testnet: row.try_get("is_testnet")?,
        finality_model: {
            let s: String = row.try_get("finality_model")?;
            s.parse()
                .map_err(|_| anyhow::anyhow!("bad finality_model: {s}"))?
        },
        block_time_ms: row.try_get("block_time_ms")?,
    })
}

fn row_to_index_target(row: &sqlx::postgres::PgRow) -> anyhow::Result<IndexTarget> {
    let kind_str: String = row.try_get("kind")?;
    let family_str: String = row.try_get("chain_family")?;
    let mode_str: String = row.try_get("mode")?;
    Ok(IndexTarget {
        id: row.try_get("id")?,
        kind: sql_to_target_kind(&kind_str)?,
        network: row.try_get("network")?,
        chain_family: sql_to_chain_family(&family_str)?,
        address: row.try_get("address")?,
        filter_spec: row.try_get("filter_spec")?,
        mode: sql_to_target_mode(&mode_str)?,
        label: row.try_get("label")?,
        owner_id: row.try_get("owner_id")?,
        created_at: row.try_get("created_at")?,
        updated_at: row.try_get("updated_at")?,
    })
}

fn row_to_raw_transaction(row: &sqlx::postgres::PgRow) -> anyhow::Result<RawTransaction> {
    Ok(RawTransaction {
        id: row.try_get("id")?,
        network: row.try_get("network")?,
        tx_hash: row.try_get("tx_hash")?,
        timestamp: row.try_get("timestamp")?,
        block_number: row.try_get("block_number")?,
        raw_metadata: row.try_get("raw_metadata")?,
        source: row.try_get("source")?,
        ingestion_run_id: row.try_get("ingestion_run_id")?,
        ingested_at: row.try_get("ingested_at")?,
    })
}

fn row_to_target_match(row: &sqlx::postgres::PgRow) -> anyhow::Result<TargetMatch> {
    Ok(TargetMatch {
        id: row.try_get("id")?,
        target_id: row.try_get("target_id")?,
        raw_transaction_id: row.try_get("raw_transaction_id")?,
        match_reason: row.try_get("match_reason")?,
        matched_at: row.try_get("matched_at")?,
    })
}

fn row_to_ingestion_run(row: &sqlx::postgres::PgRow) -> anyhow::Result<IngestionRun> {
    Ok(IngestionRun {
        id: row.try_get("id")?,
        target_id: row.try_get("target_id")?,
        network: row.try_get("network")?,
        source: row.try_get("source")?,
        mode: row.try_get("mode")?,
        status: row.try_get("status")?,
        started_at: row.try_get("started_at")?,
        finished_at: row.try_get("finished_at")?,
        records_written: row.try_get("records_written")?,
        error_message: row.try_get("error_message")?,
        cursor_state: row.try_get("cursor_state")?,
    })
}

fn row_to_checkpoint(row: &sqlx::postgres::PgRow) -> anyhow::Result<Checkpoint> {
    Ok(Checkpoint {
        id: row.try_get("id")?,
        target_id: row.try_get("target_id")?,
        network: row.try_get("network")?,
        source: row.try_get("source")?,
        cursor: row.try_get("cursor")?,
        updated_at: row.try_get("updated_at")?,
    })
}

fn row_to_dataset_version(row: &sqlx::postgres::PgRow) -> anyhow::Result<DatasetVersion> {
    let status_str: String = row.try_get("status")?;
    Ok(DatasetVersion {
        id: row.try_get("id")?,

use std::time::Duration;

use chrono::Utc;
use serde::{Deserialize, Serialize};
use spectraplex_core::connector::{ConnectorCapabilities, MarketFilterSpec};
use spectraplex_core::models::{Chain, ChainIngestor, IndexerCheckpoint, Transaction};
use spectraplex_core::v2::{
    ChainFamily, IndexTarget, IngestionBatch, RawTransaction, TargetKind, TargetMode,
};
use tokio::sync::mpsc;
use tracing::info;
use uuid::Uuid;

use crate::hyperliquid_ws::HyperliquidWsClient;

const HL_INFO_URL: &str = "https://api.hyperliquid.xyz/info";

pub struct HyperliquidAdapter {
    client: reqwest::Client,
    base_url: String,
    ws_url: Option<String>,
}

// --- Request types ---

#[derive(Serialize)]
struct UserFillsRequest<'a> {
    r#type: &'static str,
    user: &'a str,
}

#[derive(Serialize)]
struct UserFundingRequest<'a> {
    r#type: &'static str,
    user: &'a str,
    #[serde(rename = "startTime")]
    start_time: i64,
}

#[derive(Serialize)]
struct UserLedgerUpdatesRequest<'a> {
    r#type: &'static str,
    user: &'a str,
    #[serde(rename = "startTime")]
    start_time: i64,
}

#[derive(Serialize)]
struct FundingHistoryRequest<'a> {
    r#type: &'static str,
    coin: &'a str,
    #[serde(rename = "startTime")]
    start_time: i64,
    #[serde(rename = "endTime", skip_serializing_if = "Option::is_none")]
    end_time: Option<i64>,
}

// --- Response types (for deserialization) ---

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct HlFill {
    pub coin: String,
    pub px: String,
    pub sz: String,
    pub side: String,
    pub time: u64,
    pub hash: String,
    #[serde(rename = "startPosition")]
    pub start_position: Option<String>,
    pub dir: Option<String>,
    #[serde(rename = "closedPnl")]
    pub closed_pnl: Option<String>,
    pub fee: Option<String>,
    pub tid: Option<u64>,
    pub oid: Option<u64>,
    #[serde(rename = "feeToken")]
    pub fee_token: Option<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct HlFundingEntry {
    pub time: u64,
    pub coin: String,
    #[serde(rename = "usdc")]
    pub usdc: String,
    #[serde(rename = "fundingRate")]
    pub funding_rate: Option<String>,
    pub hash: Option<String>,
    #[serde(rename = "nSamples")]
    pub n_samples: Option<u64>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct HlLedgerUpdate {
    pub time: u64,
    pub hash: String,
    pub delta: serde_json::Value,
}

/// Market-level funding rate record from the `fundingHistory` REST endpoint.
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct HlFundingRate {
    pub coin: String,
    #[serde(rename = "fundingRate")]
    pub funding_rate: String,
    pub premium: String,
    pub time: u64,
}

impl Default for HyperliquidAdapter {
    fn default() -> Self {
        Self::new()
    }
}

impl HyperliquidAdapter {
    pub fn new() -> Self {
        Self {
            client: Self::build_client(),
            base_url: HL_INFO_URL.to_string(),
            ws_url: None,
        }
    }

    pub fn with_base_url(base_url: &str) -> Self {
        Self {
            client: Self::build_client(),
            base_url: base_url.to_string(),
            ws_url: None,
        }
    }

    pub fn with_urls(base_url: &str, ws_url: &str) -> Self {
        Self {
            client: Self::build_client(),
            base_url: base_url.to_string(),
            ws_url: Some(ws_url.to_string()),
        }
    }

    fn build_client() -> reqwest::Client {
        reqwest::Client::builder()
            .timeout(Duration::from_secs(30))
            .connect_timeout(Duration::from_secs(10))
            .build()
            .expect("failed to build HTTP client")
    }

    // -----------------------------------------------------------------------
    // User-level REST methods (wallet targets)
    // -----------------------------------------------------------------------

    pub async fn fetch_user_fills(&self, wallet: &str) -> anyhow::Result<Vec<HlFill>> {
        let body = UserFillsRequest {
            r#type: "userFills",
            user: wallet,
        };
        let resp = self.client.post(&self.base_url).json(&body).send().await?;
        let status = resp.status();
        if !status.is_success() {
            let text = resp.text().await.unwrap_or_default();
            anyhow::bail!("Hyperliquid userFills returned {}: {}", status, text);
        }
        let fills: Vec<HlFill> = resp.json().await?;
        Ok(fills)
    }

    pub async fn fetch_user_funding(
        &self,
        wallet: &str,
        start_time: i64,
    ) -> anyhow::Result<Vec<HlFundingEntry>> {
        let body = UserFundingRequest {
            r#type: "userFunding",
            user: wallet,
            start_time,
        };
        let resp = self.client.post(&self.base_url).json(&body).send().await?;
        let status = resp.status();
        if !status.is_success() {
            let text = resp.text().await.unwrap_or_default();
            anyhow::bail!("Hyperliquid userFunding returned {}: {}", status, text);
        }
        let funding: Vec<HlFundingEntry> = resp.json().await?;
        Ok(funding)
    }

    pub async fn fetch_user_ledger_updates(
        &self,
        wallet: &str,
        start_time: i64,
    ) -> anyhow::Result<Vec<HlLedgerUpdate>> {
        let body = UserLedgerUpdatesRequest {
            r#type: "userNonFundingLedgerUpdates",
            user: wallet,
            start_time,
        };
        let resp = self.client.post(&self.base_url).json(&body).send().await?;
        let status = resp.status();
        if !status.is_success() {
            let text = resp.text().await.unwrap_or_default();
            anyhow::bail!(
                "Hyperliquid userNonFundingLedgerUpdates returned {}: {}",
                status,
                text
            );
        }
        let updates: Vec<HlLedgerUpdate> = resp.json().await?;
        Ok(updates)
    }

    // -----------------------------------------------------------------------
    // Market-level REST methods (market targets)
    // -----------------------------------------------------------------------

    /// Fetch historical funding rates for a specific coin.
    ///
    /// Uses the `fundingHistory` REST endpoint which returns market-wide
    /// funding rate records (not per-user). This is the primary market-level
    /// backfill data source since Hyperliquid does not expose a `recentTrades`
    /// REST endpoint.
    pub async fn fetch_funding_history(
        &self,
        coin: &str,
        start_time: i64,
        end_time: Option<i64>,
    ) -> anyhow::Result<Vec<HlFundingRate>> {
        let body = FundingHistoryRequest {
            r#type: "fundingHistory",
            coin,
            start_time,
            end_time,
        };
        let resp = self.client.post(&self.base_url).json(&body).send().await?;
        let status = resp.status();
        if !status.is_success() {
            let text = resp.text().await.unwrap_or_default();
            anyhow::bail!("Hyperliquid fundingHistory returned {}: {}", status, text);
        }
        let rates: Vec<HlFundingRate> = resp.json().await?;
        Ok(rates)
    }

    // -----------------------------------------------------------------------
    // V2 Connector internal backfill methods
    // -----------------------------------------------------------------------

    /// Wallet backfill: fetch fills, funding, and ledger updates for a wallet
    /// address, producing target-agnostic `RawTransaction` records.
    async fn wallet_backfill(
        &self,
        target: &IndexTarget,
        cursor: Option<&serde_json::Value>,
        limit: usize,
    ) -> anyhow::Result<IngestionBatch> {
        let wallet_str = target
            .address
            .as_deref()
            .ok_or_else(|| anyhow::anyhow!("wallet target must have an address"))?;

        let resume_ms = cursor_to_start_time_ms(cursor);
        let network = &target.network;
        let mut records = Vec::new();

        // 1. Fills — no startTime param, filter client-side
        let fills = self.fetch_user_fills(wallet_str).await?;
        for fill in fills
            .iter()
            .filter(|f| f.time >= resume_ms as u64)
            .take(limit)
        {
            let raw = serde_json::to_value(fill)?;
            records.push(RawTransaction {
                id: Uuid::new_v4(),
                network: network.clone(),
                tx_hash: fill.hash.clone(),
                timestamp: (fill.time / 1000) as i64,
                block_number: None,
                raw_metadata: serde_json::json!({ "type": "fill", "data": raw }),
                source: "hl-rest-wallet-backfill".to_string(),
                ingestion_run_id: None,
                ingested_at: Utc::now(),
            });
        }

        // 2. Funding payments
        let remaining = limit.saturating_sub(records.len());
        if remaining > 0 {
            let funding = self.fetch_user_funding(wallet_str, resume_ms).await?;
            for entry in funding.iter().take(remaining) {
                let raw = serde_json::to_value(entry)?;
                let hash = entry
                    .hash
                    .clone()
                    .unwrap_or_else(|| format!("funding-{}-{}", entry.coin, entry.time));
                records.push(RawTransaction {
                    id: Uuid::new_v4(),
                    network: network.clone(),
                    tx_hash: hash,
                    timestamp: (entry.time / 1000) as i64,
                    block_number: None,
                    raw_metadata: serde_json::json!({ "type": "funding", "data": raw }),
                    source: "hl-rest-wallet-backfill".to_string(),
                    ingestion_run_id: None,
                    ingested_at: Utc::now(),
                });
            }
        }

        // 3. Non-funding ledger updates
        let remaining = limit.saturating_sub(records.len());
        if remaining > 0 {
            let ledger_updates = self
                .fetch_user_ledger_updates(wallet_str, resume_ms)
                .await?;
            for update in ledger_updates.iter().take(remaining) {
                let raw = serde_json::to_value(update)?;
                records.push(RawTransaction {
                    id: Uuid::new_v4(),
                    network: network.clone(),
                    tx_hash: update.hash.clone(),
                    timestamp: (update.time / 1000) as i64,
                    block_number: None,
                    raw_metadata: serde_json::json!({ "type": "ledger_update", "data": raw }),
                    source: "hl-rest-wallet-backfill".to_string(),
                    ingestion_run_id: None,
                    ingested_at: Utc::now(),
                });
            }
        }

        info!(
            "Hyperliquid V2 wallet backfill: collected {} records for {}",
            records.len(),
            wallet_str
        );

        Ok(IngestionBatch {
            records,
            checkpoint: None,
            run_metadata: None,
        })
    }

    /// Market backfill: fetch funding rate history for a coin, producing
    /// target-agnostic `RawTransaction` records.
    ///
    /// Hyperliquid does not expose a `recentTrades` REST endpoint, so the
    /// primary market-level backfill data source is `fundingHistory`. The WS
    /// `trades` channel provides real-time market trade data for streaming.
    async fn market_backfill(
        &self,
        target: &IndexTarget,
        cursor: Option<&serde_json::Value>,
        limit: usize,
    ) -> anyhow::Result<IngestionBatch> {
        let coin = target
            .address
            .as_deref()
            .ok_or_else(|| anyhow::anyhow!("market target must have an address (coin symbol)"))?;

        let start_time_ms = cursor_to_start_time_ms(cursor);
        let network = &target.network;

        // Parse filter spec for data_types if present
        let _filter: MarketFilterSpec = match &target.filter_spec {
            Some(v) => serde_json::from_value(v.clone())?,
            None => MarketFilterSpec::default(),
        };

        let rates = self
            .fetch_funding_history(coin, start_time_ms, None)
            .await?;

        let records: Vec<RawTransaction> = rates
            .iter()
            .take(limit)
            .map(|rate| {
                let raw = serde_json::to_value(rate).unwrap_or_default();
                let hash = format!("funding-rate-{}-{}", rate.coin, rate.time);
                RawTransaction {
                    id: Uuid::new_v4(),
                    network: network.clone(),
                    tx_hash: hash,
                    timestamp: (rate.time / 1000) as i64,
                    block_number: None,
                    raw_metadata: serde_json::json!({ "type": "funding_rate", "data": raw }),
                    source: "hl-rest-market-backfill".to_string(),
                    ingestion_run_id: None,
                    ingested_at: Utc::now(),
                }
            })
            .collect();

        info!(
            "Hyperliquid V2 market backfill: collected {} records for {}",
            records.len(),
            coin
        );

        Ok(IngestionBatch {
            records,
            checkpoint: None,
            run_metadata: None,
        })
    }
}

