    vec![HlPositionChange {
        id: Uuid::new_v4(),
        raw_transaction_id: raw_tx_id,
        network: network.to_string(),
        coin: coin.to_string(),
        side: side.to_string(),
        size_delta,
        price,
        direction: Some("Liquidation".to_string()),
        source_event: "liquidation".to_string(),
        dataset_version_id: None,
        created_at: Utc::now(),
    }]
}

