        let entries = parse_hyperliquid_transaction(&tx).unwrap();
        // Trade + Fee + Income (PnL)
        assert_eq!(entries.len(), 3);

        let trade = &entries[0];
        assert_eq!(trade.amount, BigDecimal::from_str("-0.5").unwrap());

        let income = &entries[2];
