        args.add(c.created_at).map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    query.push_str(
        " ON CONFLICT (raw_transaction_id, coin, side, source_event) \
         WHERE raw_transaction_id IS NOT NULL DO NOTHING",
    );
    Ok((query, args))
}

