        let all = [
            TargetKind::Wallet,
            TargetKind::Contract,
            TargetKind::Program,
            TargetKind::Account,
            TargetKind::TopicFilter,
            TargetKind::Market,
            TargetKind::Pool,
            TargetKind::Protocol,
        ];
        assert_eq!(all.len(), 8);
        for tk in all {
            let s = target_kind_to_sql(&tk);
            let back = sql_to_target_kind(s).unwrap();
            assert_eq!(tk, back, "roundtrip failed for {tk:?}");
        }
    }

